+    g_assert_true(ws_packet_endpoints_parse(229, ipv6_udp, sizeof ipv6_udp, &ep));  /* raw IPv6 */
+    check_ipv6_udp(&ep);
+    g_assert_false(PARSE(105, ethernet_ipv4_hdr, ipv4_tcp, &ep));   /* a link type we don't handle */
